SELECT id, field_key, label, data_type, editable_default, value_source, source_path, source_config, default_value, mask_rule, format_pattern, sort_order, is_enabled, remark, created_by, created_at, updated_by, updated_at, is_deleted, deleted_at, deleted_by, tenant_id FROM ( SELECT id, field_key, label, data_type, editable_default, value_source, source_path, source_config, default_value, mask_rule, format_pattern, sort_order, is_enabled, remark, created_by, created_at, updated_by, updated_at, is_deleted, deleted_at, deleted_by, tenant_id FROM `emr_metadata_field_def` WHERE is_deleted = 0 AND is_enabled = #{isEnabled}
AND value_source = #{valueSource}
AND field_key LIKE CONCAT('%', #{keyword}, '%') UNION ALL SELECT id, field_key, label, data_type, editable_default, value_source, source_path, source_config, default_value, mask_rule, format_pattern, sort_order, is_enabled, remark, created_by, created_at, updated_by, updated_at, is_deleted, deleted_at, deleted_by, tenant_id FROM `emr_metadata_field_def` WHERE is_deleted = 0 AND is_enabled = #{isEnabled}
AND value_source = #{valueSource}
AND label LIKE CONCAT('%', #{keyword}, '%') AND field_key NOT LIKE CONCAT('%', #{keyword}, '%') ) t ORDER BY sort_order ASC

SELECT COUNT(*) FROM (
    SELECT id FROM `emr_metadata_field_def`
    WHERE is_deleted = 0
      AND is_enabled = #{isEnabled}

      AND value_source = #{valueSource}

      AND field_key LIKE CONCAT('%', #{keyword}, '%')
    UNION ALL
    SELECT id FROM `emr_metadata_field_def`
    WHERE is_deleted = 0
      AND is_enabled = #{isEnabled}

      AND value_source = #{valueSource}

      AND label LIKE CONCAT('%', #{keyword}, '%')
      AND field_key NOT LIKE CONCAT('%', #{keyword}, '%')
) t
